{
  "assessments": [
    {
      "proposition_id": "P1",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "The summary does not identify the amendment to § 49-3-103(d)(3) or its insertion of public charter schools."
    },
    {
      "proposition_id": "P2",
      "status": "partial",
      "summary_quote": "It would require the state department of education to allocate the state share of student-generated funding directly to public charter schools rather than to the local education agency (LEA).",
      "rationale": "Covers direct allocation of the charter school state share, but omits the general allocation rule for the duration of LEA membership and the exception retaining subdivision (c)(3) funding with the department."
    },
    {
      "proposition_id": "P3",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "The summary does not address membership dates or the funding extension for early graduates."
    },
    {
      "proposition_id": "P4",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "The summary does not identify the amendment adding public charter schools throughout § 49-3-316(c)."
    },
    {
      "proposition_id": "P5",
      "status": "partial",
      "summary_quote": "It also requires the commissioner, working with the comptroller of the treasury, to create a standardized financial accounting and reporting system for all public charter schools to track how funds are used.",
      "rationale": "Covers the responsible officials and standardized system, but omits revision as necessary, forms or documentation, year-to-year and agency-to-agency comparisons, and identification of funding sources."
    },
    {
      "proposition_id": "P6",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "Creating a reporting system does not convey the separate duty to review charter school fiscal records and safeguard expenditures."
    },
    {
      "proposition_id": "P7",
      "status": "partial",
      "summary_quote": "The commissioner may also require charter schools to follow certain financial requirements established for LEAs.",
      "rationale": "Conveys discretionary authority but omits the state-funding eligibility condition and the limitation to requirements established in § 49-3-316."
    },
    {
      "proposition_id": "P8",
      "status": "partial",
      "summary_quote": "Under the proposal, local boards of education must allocate specific local student-generated funds, average per pupil funds above those required by the Tennessee Investment in Student Achievement (TISA), and current year funds for new students to public charter schools.",
      "rationale": "Conveys allocation of local student-generated funds but omits the prior-year membership basis and alignment of that allocation with TISA."
    },
    {
      "proposition_id": "P9",
      "status": "partial",
      "summary_quote": "Under the proposal, local boards of education must allocate specific local student-generated funds, average per pupil funds above those required by the Tennessee Investment in Student Achievement (TISA), and current year funds for new students to public charter schools.",
      "rationale": "Covers above-TISA average per-pupil funding, but omits that it includes current-year district state and local funds and is allocated for each prior-year charter member student."
    },
    {
      "proposition_id": "P10",
      "status": "partial",
      "summary_quote": "Under the proposal, local boards of education must allocate specific local student-generated funds, average per pupil funds above those required by the Tennessee Investment in Student Achievement (TISA), and current year funds for new students to public charter schools.",
      "rationale": "Mentions current-year funding for new students, but does not specify per-student state and local funds received by the LEA or the membership increase over the prior year."
    },
    {
      "proposition_id": "P11",
      "status": "full",
      "summary_quote": "Local boards must also provide appropriate federal funds, such as IDEA and ESEA funds, through joint agreements or sub-grants.",
      "rationale": "Conveys the local boards' obligation to provide appropriate federal allocations, including IDEA and ESEA funds."
    },
    {
      "proposition_id": "P12",
      "status": "partial",
      "summary_quote": "It would require the state department of education to allocate the state share of student-generated funding directly to public charter schools rather than to the local education agency (LEA).",
      "rationale": "Covers direct department allocation but omits the amount's basis in prior-year member students and alignment with TISA."
    },
    {
      "proposition_id": "P13",
      "status": "partial",
      "summary_quote": "Local boards must also provide appropriate federal funds, such as IDEA and ESEA funds, through joint agreements or sub-grants.",
      "rationale": "Covers the two disbursement routes but omits the LEA authorization limitation, shared-services purpose, equitable-share calculation based on eligible students, and compliance with department policies and procedures."
    },
    {
      "proposition_id": "P14",
      "status": "partial",
      "summary_quote": "LEAs would be required to include the per pupil amount of local money passed to charter schools in their budgets",
      "rationale": "Covers budget disclosure of per-pupil local funding, but omits the upcoming-year scope, required calculations, and requirement to base that year's allocations on those calculations."
    },
    {
      "proposition_id": "P15",
      "status": "partial",
      "summary_quote": "LEAs would be required to include the per pupil amount of local money passed to charter schools in their budgets and distribute these funds in at least nine equal installments",
      "rationale": "Covers the local-fund installment requirement but omits distribution in the same manner as state funds."
    },
    {
      "proposition_id": "P16",
      "status": "partial",
      "summary_quote": "with adjustments made in October, February, and June.",
      "rationale": "Identifies the required adjustment months but omits the bases of changes in revenue, student membership, or student services."
    },
    {
      "proposition_id": "P17",
      "status": "omitted",
      "summary_quote": "",
      "rationale": "The summary does not describe charter schools' obligation to spend funds according to their submitted or governing-body-revised budgets, subject to state and federal law."
    },
    {
      "proposition_id": "P18",
      "status": "full",
      "summary_quote": "Sections 1 and 3 would take effect upon becoming law. Sections 2 and 4 would take effect for rulemaking upon becoming law and for all other purposes on July 1, 2025.",
      "rationale": "Accurately conveys all effective dates and the distinction between rulemaking and other purposes."
    }
  ]
}
